// A small program for exercising the time travel debugger.
class Cart {
  constructor(owner) {
    this.owner = owner;
    this.items = [];
  }

  add(name, price, qty = 1) {
    const item = { name, price, qty };
    this.items.push(item);
    return item;
  }

  total() {
    let sum = 0;
    for (const item of this.items) {
      sum += item.price * item.qty;
    }
    return applyDiscount(sum, this.owner);
  }
}

function applyDiscount(amount, owner) {
  const rate = owner.vip ? 0.2 : 0;
  const discounted = amount * (1 - rate);
  return Math.round(discounted * 100) / 100;
}

function parseOrder(line) {
  const [name, price, qty] = line.split(",");
  if (!name) {
    throw new Error(`bad order line: "${line}"`);
  }
  return { name: name.trim(), price: Number(price), qty: Number(qty) };
}

const delay = ms => new Promise(resolve => setTimeout(resolve, ms));

async function checkout(cart) {
  await delay(20);
  const total = cart.total();
  console.log(`${cart.owner.name} pays ${total}`);
  return total;
}

async function main() {
  const orders = ["apple, 0.5, 6", "bread, 2.25, 1", ",1,1", "cheese, 7.8, 2"];
  const alice = new Cart({ name: "Alice", vip: true });
  const bob = new Cart({ name: "Bob", vip: false });

  orders.forEach((line, i) => {
    try {
      const order = parseOrder(line);
      const cart = i % 2 ? bob : alice;
      cart.add(order.name, order.price, order.qty);
    } catch (e) {
      console.log("skipped:", e.message);
    }
  });

  const totals = [];
  for (const cart of [alice, bob]) {
    totals.push(await checkout(cart));
  }
  console.log("grand total", totals.reduce((a, b) => a + b, 0));
}

main();
